import random

def is_triangle_free(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

def get_maximal_triangle_free(n, initial_edges):
    edges = set(tuple(sorted(e)) for e in initial_edges)

    # Try to add edges randomly
    all_possible_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if tuple(sorted((i, j))) not in edges:
                all_possible_edges.append(tuple(sorted((i, j))))

    random.shuffle(all_possible_edges)

    for u, v in all_possible_edges:
        if is_triangle_free(n, edges | {(u, v)}):
            edges.add((u, v))

    return edges

